-- =============================================================================
-- NINHO — CATÁLOGO SEMÂNTICO: 02_meta_metrica.sql (PROJETO: GLD)
-- =============================================================================

MERGE INTO DW_GLD.META_METRICA dst
USING (SELECT 'GLD' AS PROJETO, 'QTD_TOTAL_LICITACAO_CONTRATO' AS NOME_METRICA, 'Volume Total de Licitacao_Contrato — Contagem total de registros na fato FATO_LICITACAO_CONTRATO' AS DESCRICAO_NEGOCIO, 'COUNT(1)' AS FORMULA_SQL, 'ADITIVA' AS TIPO_ADITIVIDADE, 'DTC_REFERENCIA' AS DATA_REFERENCIA, 'Nenhum' AS FILTROS_OBRIGATORIOS, 'VW_GLD_KPI_LICITACAO_CONTRATO' AS DIMENSOES_PERMITIDAS, 'INTEIRO' AS UNIDADE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.NOME_METRICA = src.NOME_METRICA)
WHEN MATCHED THEN UPDATE SET dst.FORMULA_SQL = src.FORMULA_SQL, dst.DIMENSOES_PERMITIDAS = src.DIMENSOES_PERMITIDAS
WHEN NOT MATCHED THEN INSERT (PROJETO, NOME_METRICA, DESCRICAO_NEGOCIO, FORMULA_SQL, TIPO_ADITIVIDADE, DATA_REFERENCIA, FILTROS_OBRIGATORIOS, DIMENSOES_PERMITIDAS, UNIDADE)
VALUES (src.PROJETO, src.NOME_METRICA, src.DESCRICAO_NEGOCIO, src.FORMULA_SQL, src.TIPO_ADITIVIDADE, src.DATA_REFERENCIA, src.FILTROS_OBRIGATORIOS, src.DIMENSOES_PERMITIDAS, src.UNIDADE);

MERGE INTO DW_GLD.META_METRICA dst
USING (SELECT 'GLD' AS PROJETO, 'SUM_QTD_ITENS_CONTRATO' AS NOME_METRICA, 'Somatório de QTD_ITENS_CONTRATO — Soma consolidada da coluna QTD_ITENS_CONTRATO em FATO_LICITACAO_CONTRATO' AS DESCRICAO_NEGOCIO, 'SUM(NVL(QTD_ITENS_CONTRATO, 0))' AS FORMULA_SQL, 'ADITIVA' AS TIPO_ADITIVIDADE, 'DTC_REFERENCIA' AS DATA_REFERENCIA, 'Nenhum' AS FILTROS_OBRIGATORIOS, 'VW_GLD_KPI_LICITACAO_CONTRATO' AS DIMENSOES_PERMITIDAS, 'NUMERICO' AS UNIDADE FROM DUAL) src
